#!/usr/bin/env python3
"""Pack local web sources into flash assets; Sass is optional and host-only."""
import argparse
import gzip
import hashlib
from pathlib import Path
import re

ROOT=Path(__file__).resolve().parents[1]
WEB=ROOT/'firmware/web'
INCLUDE=ROOT/'firmware/include'

def write_changed(path,data):
    if not path.exists() or path.read_bytes()!=data:path.write_bytes(data)

def compile_bootstrap():
    import sass  # Optional host dependency: libsass==0.23.0
    css=sass.compile(filename=str(WEB/'bootstrap.scss'),output_style='compressed')
    css=re.sub(r'/\*# sourceMappingURL=.*?\*/','',css)
    css='/*! Bootstrap v5.3.8 | MIT | github.com/twbs/bootstrap/blob/v5.3.8/LICENSE */\n'+css
    write_changed(WEB/'bootstrap.min.css',css.encode())

def build_assets():
    lines=['#pragma once','#include <Arduino.h>',
           '// Generated by scripts/build_web_assets.py. See firmware/web/README.md.']
    paths={};records=[]
    for name,file,mime in [('BOOTSTRAP_CSS','bootstrap.min.css','text/css; charset=utf-8'),
                           ('APP_CSS','app.css','text/css; charset=utf-8'),
                           ('APP_JS','app.js','application/javascript; charset=utf-8'),
                           ('SCENE_ICONS','scene-icons.svg','image/svg+xml'),
                           ('PROJECT_ICON','coloplay.svg','image/svg+xml')]:
        raw=(WEB/file).read_bytes();packed=gzip.compress(raw,compresslevel=9,mtime=0)
        digest=hashlib.sha256(packed).hexdigest()[:12]
        path='/assets/'+file.rsplit('.',1)[0]+'-'+digest+'.'+file.rsplit('.',1)[1]
        paths[name]=path;symbol='kWeb'+name
        lines.append('const uint8_t '+symbol+'[] PROGMEM = {')
        for at in range(0,len(packed),20):lines.append('  '+','.join('0x%02x'%b for b in packed[at:at+20])+',')
        lines.append('};');records.append((path,symbol,mime))
        print(file+': '+str(len(raw))+' raw / '+str(len(packed))+' gzip bytes')
    lines+=['struct WebAsset { const char *path; const uint8_t *data; size_t length; const char *type; };',
            'const WebAsset kWebAssets[] = {']
    for path,symbol,mime in records:lines.append('  {"'+path+'",'+symbol+',sizeof('+symbol+'),"'+mime+'"},')
    lines+=['};',''];write_changed(INCLUDE/'web_assets.h','\n'.join(lines).encode())
    pages=['#pragma once','#include <Arduino.h>','// Generated from firmware/web/ by scripts/build_web_assets.py.']
    for symbol,file in [('kDemoPage','index.html'),('kUpdatePage','update.html')]:
        html=(WEB/file).read_text()
        for token,path in paths.items():html=html.replace('{{'+token+'}}',path)
        if '{{' in html or ')WEB"' in html:raise ValueError('unresolved asset or unsafe raw-string delimiter')
        pages.append('const char '+symbol+'[] PROGMEM = R"WEB('+html+')WEB";')
    write_changed(INCLUDE/'web_ui.h',('\n'.join(pages)+'\n').encode())

if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--compile-bootstrap',action='store_true')
    args=parser.parse_args()
    if args.compile_bootstrap:compile_bootstrap()
    build_assets()
